            cur.execute("""\n                INSERT INTO transactions (product_id, type, quantity, user_id, reason)
                VALUES (%s, %s, %s, %s, %s)
                RETURNING id, product_id, type, quantity, user_id, date, reason
            """, (product_id, transaction_type, quantity, user_id, reason))
